function gotkilled()
{
   _root.diesound();
   if(_name != "double")
   {
      _root.pgsdata[PLAYERNUMBER - 1][2] += 1;
   }
   lives -= 1;
   _root.pDepth += 1;
   newmc = _root.attachMovie("fx_bling","trash" + _root.pDepth,_root.pDepth);
   if(gothitby == _root.p1name)
   {
      newmc.asdf = _root.player1;
      _root.pgsdata[0][1] += 1;
      if(_root.gamemode == 4)
      {
         _root.player1.UPGRADE();
      }
   }
   else if(gothitby == _root.p2name)
   {
      newmc.asdf = _root.player2;
      _root.pgsdata[1][1] += 1;
      if(_root.gamemode == 4)
      {
         _root.player2.UPGRADE();
      }
   }
   else if(gothitby == _root.p3name)
   {
      newmc.asdf = _root.player3;
      _root.pgsdata[2][1] += 1;
      if(_root.gamemode == 4)
      {
         _root.player3.UPGRADE();
      }
   }
   else if(gothitby == _root.p4name)
   {
      newmc.asdf = _root.player4;
      _root.pgsdata[3][1] += 1;
      if(_root.gamemode == 4)
      {
         _root.player4.UPGRADE();
      }
   }
   newmc.mod = 1;
   if(cheapshottimer < 120)
   {
      newmc.mod = 2;
   }
   else if(greedykill)
   {
      newmc.mod = 3;
   }
   else if(hitbynade)
   {
      newmc.mod = 4;
   }
   if(_root.gamemode == 4)
   {
      newmc.mod = 5;
      newmc.leveldisplay = newmc.asdf.currentlevel;
   }
   if(cheapshottimer < 120)
   {
      _root.hud.killupdate(nametag.nametext.text,gothitby,2);
   }
   else if(greedykill)
   {
      _root.hud.killupdate(nametag.nametext.text,gothitby,4);
   }
   else if(hitbynade)
   {
      _root.hud.killupdate(nametag.nametext.text,gothitby,3);
   }
   else
   {
      _root.hud.killupdate(nametag.nametext.text,gothitby,1);
   }
   if(lives > 0)
   {
      respawn();
   }
   else
   {
      _root.hud.update();
      i = 0;
      while(i < _root.activeplayers.length)
      {
         if(_root.activeplayers[i] == this)
         {
            _root.activeplayers.splice(i,1);
         }
         i++;
      }
      _X = 0;
      _Y = 1100;
      _alpha = 0;
      shieldtime = 0;
      invisibletime = 0;
      jetfuel = 0;
      if(this._name == "double")
      {
         this.swapDepths(1);
         removeMovieClip(this);
      }
      delete this.onEnterFrame;
   }
}
function respawn()
{
   cheapshottimer = 0;
   gothitby = "none";
   hitbynade = false;
   if(_root.gamemode == 1)
   {
      getgun(defaultgun);
   }
   if(_root.gamemode == 2)
   {
      getgun(9);
   }
   if(_root.gamemode == 4)
   {
      getgun(currentgun);
   }
   if(_name != "double")
   {
      _Y = -1000;
      _X = _root.ground._x + _root.ground.spawnarea._x + random(_root.ground.spawnarea._width);
   }
   vy = 0;
   vx = 0;
   jumpnum = 1;
   offhandammo = 3;
   shieldtime = 0;
   invisibletime = 0;
   jetfuel = 0;
   speedtime = 0;
   minitime = 0;
   instagib.gotoAndStop(1);
   _xscale = 80;
   _yscale = 80;
   minimulti = 1;
   _root.hud.update();
   if(perknumber == 9 && _root.gamemode != 4 && _root.gamemode != 2)
   {
      randgun = random(57) + 10;
      getgun(randgun);
   }
}
function startwalk()
{
   if(leg1._currentframe == 1)
   {
      leg1.gotoAndPlay(2);
      leg2.gotoAndPlay(2);
   }
}
function SELFDESTRUCT()
{
   _root.CP("fx_ex6",_X,_Y - 20,0);
   i = 0;
   while(i < 5)
   {
      _root.CP("fx_ex5",_X,_Y - 20,0);
      i++;
   }
   i = 0;
   while(i < 5)
   {
      _root.CP("fx_ex3",_X,_Y - 20,0);
      i++;
   }
   j = 0;
   while(j < 5)
   {
      _root.CP("fx_blood",_X,_Y,0,0);
      j++;
   }
   _root.CP("fx_combo",_X,_Y - 50,0,-5);
   _root.CP("fx_bloodstain",_X,_Y,0,0);
   gotkilled();
}
function spawnfriend()
{
   newmc = _root.attachMovie("playerAI","double",-5);
   newmc._x = _X;
   newmc._y = _Y;
   newmc.asdf = this.PLAYERNUMBER;
}
function lifebling()
{
   _root.pDepth += 1;
   newmc = _root.attachMovie("fx_bling","trash" + _root.pDepth,_root.pDepth);
   newmc.asdf = this;
   newmc.mod = 6;
}
function UPGRADE()
{
   currentlevel += 1;
   switch(currentlevel)
   {
      case 1:
         currentgun = 2;
         break;
      case 2:
         currentgun = 29;
         break;
      case 3:
         currentgun = 19;
         break;
      case 4:
         currentgun = 46;
         break;
      case 5:
         currentgun = 13;
         break;
      case 6:
         currentgun = 51;
         break;
      case 7:
         currentgun = 50;
         break;
      case 8:
         currentgun = 11;
         break;
      case 9:
         currentgun = 38;
         break;
      case 10:
         currentgun = 33;
         break;
      case 11:
         currentgun = 58;
         break;
      case 12:
         currentgun = 62;
         break;
      case 13:
         currentgun = 66;
         break;
      case 14:
         currentgun = 65;
         break;
      case 15:
         currentgun = 44;
   }
   if(currentlevel == 16)
   {
      j = 0;
      while(j < _root.activeplayers.length)
      {
         if(_root.activeplayers[j]._name != this._name)
         {
            _root.activeplayers[j].lives = 0;
            _root.activeplayers[j].killself = true;
         }
         j++;
      }
   }
   else
   {
      getgun(currentgun);
   }
}
